    v_proj_id INT := (SELECT id FROM projects WHERE project_code = 'pid-14' AND deleted_at IS NULL LIMIT 1);
    v_bs_id INT := (SELECT id FROM billing_statuses WHERE name = 'Training' LIMIT 1);
    v_sys_id INT := COALESCE((SELECT id FROM users WHERE username = 'system' LIMIT 1), 1);
BEGIN
    IF v_emp_id IS NOT NULL AND v_proj_id IS NOT NULL THEN
        INSERT INTO allocations (
            employee_id, project_id, allocation_percentage, billing_percentage,
            billing_status_id, allocated_date, deallocated_date, effective_date,
            is_active, notes, created_by
        ) VALUES (
            v_emp_id, v_proj_id, 100, 0,
            v_bs_id, '2025-07-24', '2025-08-03', '2025-07-24',
            TRUE, NULL, v_sys_id
        )
        ON CONFLICT (employee_id, project_id) WHERE deleted_at IS NULL AND is_active = true
        DO UPDATE SET
            allocation_percentage = EXCLUDED.allocation_percentage,
            billing_percentage = EXCLUDED.billing_percentage,
            billing_status_id = COALESCE(EXCLUDED.billing_status_id, allocations.billing_status_id),
            allocated_date = COALESCE(EXCLUDED.allocated_date, allocations.allocated_date),
            deallocated_date = EXCLUDED.deallocated_date,
            notes = COALESCE(EXCLUDED.notes, allocations.notes),
            updated_at = NOW();
    END IF;
END $$;

