-- ============ POST-SEED CLEANUP ============
-- Deactivate allocations where deallocated_date has passed
UPDATE allocations SET is_active = false WHERE deallocated_date IS NOT NULL AND deallocated_date < CURRENT_DATE AND is_active = true;
